 * Error types used while parsing a configuration document.
 *
 * `DocError` carries a bare reason string produced while parsing a single
 * line, with no line number attached yet. The line-processing loop catches
 * it and rethrows a `LineError`, which additionally carries the 1-based line
 * number so the CLI can format `error: line N: <reason>`.
 */

export class DocError extends Error {
  constructor(reason) {
    super(reason)
    this.reason = reason
  }
}

export class LineError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}
"}

