{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-7yZ5Ie/src/model.js","content":"/**
 * The document tree built by the parser, plus the operations shared between
 * table headers and dotted-key assignments: creating tables on the way,
 * walking through the last element of an array of tables, and reporting a
 * plain dotted path (as written in the source, joined by `.`, with no array
 * indices) for the parser's own error messages.
 */

import { DocError } from './errors.js'

export function makeTable() {
  return { kind: 'table', children: new Map(), headerDefined: false }
}

export function makeArrayOfTables() {
  return { kind: 'arrayOfTables', items: [] }
}

/** Joins a path of plain name segments the way parser error messages do. */
export function formatPath(names) {
  return names.join('.')
}

/**
 * Walks all but the last of `names` starting from `root`, creating tables on
 * the way and diving into the last element of any array of tables found
 * along the way. Returns the table that should hold `names[names.length-1]`
 * plus the path (from `pathPrefix`) leading up to it.
 */
export function resolveContainer(root, pathPrefix, names) {
  let node = root
  const path = pathPrefix.slice()
  for (let i = 0; i < names.length - 1; i++) {
    const seg = names[i]
    path.push(seg)
    let child = node.children.get(seg)
    if (!child) {
      child = makeTable()
      node.children.set(seg, child)
    }
    if (child.kind === 'table') {
      node = child
    } else if (child.kind === 'arrayOfTables') {
      node = child.items[child.items.length - 1]
    } else {
      throw new DocError(`${formatPath(path)} is not a table`)
    }
  }
  return { node, path }
}

/** Assigns `val` at `names` inside `root`, rejecting a key defined twice. */
export function assignDotted(root, names, val, pathPrefix) {
  const { node: parent, path } = resolveContainer(root, pathPrefix, names)
  const finalName = names[names.length - 1]
  if (parent.children.has(finalName)) {
    throw new DocError(`key ${formatPath(path.concat(finalName))} is defined twice`)
  }
  parent.children.set(finalName, val)
}
"}

