{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-7yZ5Ie/src/values.js","content":"/**
 * Parses names, dotted names and values from a single line, sharing one
 * cursor (`ctx = { line, pos }`) across strings, arrays and inline tables.
 *
 * A `#` or `;` outside a quoted string ends the line from that point on;
 * `skipWsAndComment` is the single place that applies this rule, so every
 * caller that wants to look past whitespace and a possible trailing comment
 * goes through it. The one place comments do *not* apply is while an
 * unquoted value token is being read: since a `#` glued to a token with no
 * whitespace before it becomes part of that token's text, the token scanner
 * in `parseValue` reads through it deliberately.
 */

import { DocError } from './errors.js'
import { assignDotted } from './model.js'

const NAME_CHAR = /[A-Za-z0-9_-]/

export function skipWsAndComment(ctx) {
  while (ctx.pos < ctx.line.length && (ctx.line[ctx.pos] === ' ' || ctx.line[ctx.pos] === '\t')) {
    ctx.pos++
  }
  if (ctx.pos < ctx.line.length && (ctx.line[ctx.pos] === '#' || ctx.line[ctx.pos] === ';')) {
    ctx.pos = ctx.line.length
  }
}

function parseBasicString(ctx) {
  const line = ctx.line
  let pos = ctx.pos + 1
  let out = ''
  while (true) {
    if (pos >= line.length) throw new DocError('unterminated string')
    const c = line[pos]
    if (c === '"') {
      ctx.pos = pos + 1
      return out
    }
    if (c === '\\') {
      pos++
      if (pos >= line.length) throw new DocError('unterminated string')
      const e = line[pos]
      if (e === '"') {
        out += '"'
        pos++
      } else if (e === '\\') {
        out += '\\'
        pos++
      } else if (e === 'n') {
        out += '\n'
        pos++
      } else if (e === 't') {
        out += '\t'
        pos++
      } else if (e === 'r') {
        out += '\r'
        pos++
      } else if (e === '0') {
        out += '\0'
        pos++
      } else if (e === 'u') {
        const hex = line.slice(pos + 1, pos + 5)
        if (hex.length === 4 && /^[0-9a-fA-F]{4}$/.test(hex)) {
          out += String.fromCharCode(parseInt(hex, 16))
          pos += 5
        } else {
          throw new DocError('invalid escape \\u')
        }
      } else {
        throw new DocError(`invalid escape \\${e}`)
      }
    } else {
      out += c
      pos++
    }
  }
}

function parseLiteralString(ctx) {
  const line = ctx.line
  const start = ctx.pos + 1
  let pos = start
  while (true) {
    if (pos >= line.length) throw new DocError('unterminated string')
    if (line[pos] === "'") {
      const out = line.slice(start, pos)
      ctx.pos = pos + 1
      return out
    }
    pos++
  }
}

/** Parses one name: a bare word or a quoted string. */
function parseName(ctx) {
  skipWsAndComment(ctx)
  if (ctx.pos >= ctx.line.length) throw new DocError('expected a name')
  const c = ctx.line[ctx.pos]
  if (c === '"') return parseBasicString(ctx)
  if (c === "'") return parseLiteralString(ctx)
  if (NAME_CHAR.test(c)) {
    const start = ctx.pos
    while (ctx.pos < ctx.line.length && NAME_CHAR.test(ctx.line[ctx.pos])) ctx.pos++
    return ctx.line.slice(start, ctx.pos)
  }
  throw new DocError('expected a name')
}

/** Parses names joined by `.`, with spaces and tabs allowed around each `.`. */
export function parseDottedName(ctx) {
  const names = [parseName(ctx)]
  while (true) {
    skipWsAndComment(ctx)
    if (ctx.pos < ctx.line.length && ctx.line[ctx.pos] === '.') {
      ctx.pos++
      names.push(parseName(ctx))
      continue
    }
    break
  }
  return names
}

function normalizeInt(token) {
  let t = token.replace(/_/g, '')
  let sign = ''
  if (t[0] === '+') {
    t = t.slice(1)
  } else if (t[0] === '-') {
    sign = '-'
    t = t.slice(1)
  }
  t = t.replace(/^0+(?=\d)/, '')
  if (t === '0') sign = ''
  return sign + t
}

const INT_RE = /^[+-]?[0-9]+(?:_[0-9]+)*$/
const FLOAT_RE = /^([+-]?[0-9]+(?:_[0-9]+)*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$/

function classifyBareToken(token) {
  if (token === 'true') return { kind: 'boolean', value: true }
  if (token === 'false') return { kind: 'boolean', value: false }
  if (INT_RE.test(token)) return { kind: 'integer', value: normalizeInt(token) }
  const m = FLOAT_RE.exec(token)
  if (m && (m[2] || m[3])) {
    return { kind: 'float', value: Number(token.replace(/_/g, '')) }
  }
  throw new DocError(`invalid value ${token}`)
}

/**
 * Parses one value. `path` is the dotted path (plain names, no array
 * indices) of the key this value is being assigned to, threaded through so
 * that an inline table nested anywhere inside it can report its own
 * duplicate-key errors counted from the document root.
 */
export function parseValue(ctx, path) {
  skipWsAndComment(ctx)
  const line = ctx.line
  if (ctx.pos >= line.length) throw new DocError('expected a value')
  const c = line[ctx.pos]
  if (c === ',' || c === ']' || c === '}') throw new DocError('expected a value')
  if (c === '"') return { kind: 'string', value: parseBasicString(ctx) }
  if (c === "'") return { kind: 'string', value: parseLiteralString(ctx) }
  if (c === '[') return parseArray(ctx, path)
  if (c === '{') return parseInlineTable(ctx, path)

  const start = ctx.pos
  while (ctx.pos < line.length) {
    const ch = line[ctx.pos]
    if (ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}') break
    ctx.pos++
  }
  return classifyBareToken(line.slice(start, ctx.pos))
}

function parseArray(ctx, path) {
  ctx.pos++ // skip '['
  const items = []
  skipWsAndComment(ctx)
  if (ctx.pos >= ctx.line.length) throw new DocError('unterminated array')
  if (ctx.line[ctx.pos] === ']') {
    ctx.pos++
    return { kind: 'array', items }
  }
  while (true) {
    items.push(parseValue(ctx, path))
    skipWsAndComment(ctx)
    if (ctx.pos >= ctx.line.length) throw new DocError('unterminated array')
    const c = ctx.line[ctx.pos]
    if (c === ',') {
      ctx.pos++
      skipWsAndComment(ctx)
      if (ctx.pos >= ctx.line.length) throw new DocError('unterminated array')
      if (ctx.line[ctx.pos] === ']') {
        ctx.pos++
        break
      }
      continue
    } else if (c === ']') {
      ctx.pos++
      break
    } else {
      throw new DocError('trailing text after a value')
    }
  }
  return { kind: 'array', items }
}

function parseInlineTable(ctx, path) {
  ctx.pos++ // skip '{'
  const table = { kind: 'table', children: new Map(), headerDefined: false }
  skipWsAndComment(ctx)
  if (ctx.pos >= ctx.line.length) throw new DocError('unterminated inline table')
  if (ctx.line[ctx.pos] === '}') {
    ctx.pos++
    return table
  }
  while (true) {
    const names = parseDottedName(ctx)
    skipWsAndComment(ctx)
    if (ctx.pos >= ctx.line.length || ctx.line[ctx.pos] !== '=') {
      throw new DocError('expected = in an inline table')
    }
    ctx.pos++
    const val = parseValue(ctx, path.concat(names))
    assignDotted(table, names, val, path)
    skipWsAndComment(ctx)
    if (ctx.pos >= ctx.line.length) throw new DocError('unterminated inline table')
    const c = ctx.line[ctx.pos]
    if (c === ',') {
      ctx.pos++
      continue
    } else if (c === '}') {
