{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-7yZ5Ie/src/serialize.js","content":"/**
 * Renders a parsed document tree (see `model.js`) in the two output modes:
 * `json`, canonical JSON with object members in ascending key order, and
 * `keys`, one `<path> <type>` line per node below the root.
 */

function sortedKeys(children) {
  return Array.from(children.keys()).sort()
}

function toJson(node, indent) {
  const pad = '  '.repeat(indent)
  const padIn = '  '.repeat(indent + 1)
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node.children)
      if (keys.length === 0) return '{}'
      const parts = keys.map((k) => `${padIn}${JSON.stringify(k)}: ${toJson(node.children.get(k), indent + 1)}`)
      return `{\n${parts.join(',\n')}\n${pad}}`
    }
    case 'arrayOfTables':
    case 'array': {
      const items = node.items
      if (items.length === 0) return '[]'
      const parts = items.map((it) => `${padIn}${toJson(it, indent + 1)}`)
      return `[\n${parts.join(',\n')}\n${pad}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
      return node.value
    case 'float':
      return JSON.stringify(node.value)
    default:
      throw new Error(`unreachable node kind ${node.kind}`)
  }
}

export function toJsonText(root) {
  return toJson(root, 0) + '\n'
}

function typeOf(node) {
  switch (node.kind) {
    case 'table':
      return 'table'
    case 'arrayOfTables':
    case 'array':
      return 'array'
    default:
      return node.kind
  }
}

function walkKeys(node, path, out) {
  out.push(`${path} ${typeOf(node)}`)
  if (node.kind === 'table') {
    for (const k of sortedKeys(node.children)) {
      walkKeys(node.children.get(k), `${path}.${k}`, out)
    }
  } else if (node.kind === 'arrayOfTables' || node.kind === 'array') {
    node.items.forEach((item, i) => walkKeys(item, `${path}[${i}]`, out))
  }
}

export function toKeysText(root) {
  const out = []
  for (const k of sortedKeys(root.children)) {
    walkKeys(root.children.get(k), k, out)
  }
  return out.length === 0 ? '' : out.join('\n') + '\n'
}
"}

