  switch (node.kind) {
    case 'table':
      return 'table'
    case 'arrayOfTables':
    case 'array':
      return 'array'
    default:
      return node.kind
  }
}

function walkKeys(node, path, out) {
  out.push(`${path} ${typeOf(node)}`)
  if (node.kind === 'table') {
    for (const k of sortedKeys(node.children)) {
      walkKeys(node.children.get(k), `${path}.${k}`, out)
    }
  } else if (node.kind === 'arrayOfTables' || node.kind === 'array') {
    node.items.forEach((item, i) => walkKeys(item, `${path}[${i}]`, out))
  }
